def build():
    output_path = Path(__file__).resolve().parent / "literature_corpus.json"
    corpus_data = {
        "corpus_type": "development_sample_corpus",
        "domain": "Computer Vision, Edge AI, and Machine Learning in Agriculture and Environmental Monitoring",
        "version": "1.0.0",
        "total_papers": len(PAPERS),
        "papers": PAPERS
    }
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(corpus_data, f, indent=2, ensure_ascii=False)
    print(f"Successfully generated {len(PAPERS)} papers into {output_path}")

if __name__ == "__main__":
    build()
